import {BOARDS,NICHES,id,escapeHTML as esc,phoneNumber,freshWorkspace,normalizeWorkspace,elapsed,canContact,callRecorded,taskList,dueReviewActions,calendarEvent,leadsToCsv,parseLeadCsv,suggestions,contextualTips,messageData} from './core.mjs';

const app=document.querySelector('#app');
const S={user:null,account:null,workspace:freshWorkspace(),page:'home',board:'Principal',selected:null,revision:0,dirty:false,saving:false,conflict:false,support:false,admin:null,team:null,connection:null,aiStatus:null,aiAnalysis:null,aiLoading:false,remote:[],search:'',agenda:'today',chatTab:'tips',leadTab:'notes',settingsTab:'business',menu:false,loadToken:0,draft:'',error:''};
let saveTimer,savePromise=null,mutationCount=0,polling=false,focusBeforeDialog=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v)||0);
const date=v=>v?new Date(v).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}):'Sem data';
const dateTime=v=>v?new Date(v).toLocaleString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Não informado';
const localDateTime=(v=Date.now()+3600000)=>{const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const currentLead=()=>S.workspace.leads.find(l=>l.id===S.selected)||S.workspace.leads[0];
const isAdmin=()=>S.user?.role==='super_admin';
const permission=k=>isAdmin()||S.account?.permissions?.[k]!==false;
const initials=name=>String(name||'?').split(' ').map(s=>s[0]).slice(0,2).join('').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',leads:'M4 4h6v16H4z M14 4h6v10h-6z',chat:'M21 11a9 8 0 0 1-9 8H6l-4 3 1-7a8 8 0 1 1 18-4Z',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',arrow:'M5 12h14 M13 6l6 6-6 6',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M18 6 6 18',phone:'M7 3 3 5c0 8 8 16 16 16l2-4-5-3-2 2-6-6 2-2Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M16 16l5 5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',logout:'M9 3H3v18h6 M8 12h13 M16 7l5 5-5 5',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z m-4 10 3 3 5-6',notes:'M5 3h14v18H5Z M8 8h8 M8 12h8 M8 16h5',trend:'M3 17 9 11l4 3 8-10 M15 4h6v6',back:'M19 12H5 M11 6l-6 6 6 6',menu:'M4 6h16 M4 12h16 M4 18h16'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.spark}"/></svg>`}
const button=(label,action,kind='secondary',attrs='')=>`<button ${/type=/.test(attrs)?'':'type="button"'} class="btn ${kind}" data-action="${action}" ${attrs}>${label}</button>`;
const empty=(title,description,action='lead')=>`<div class="empty"><span class="empty-symbol">${icon('leads')}</span><h3>${title}</h3><p>${description}</p>${action?button(icon('plus')+' Adicionar contato',action,'primary'):''}</div>`;
const field=(label,name,value='',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}" ${extra}></label>`;
const textarea=(label,name,value='',extra='')=>`<label class="field"><span>${label}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const select=(label,name,values,value)=>`<label class="field"><span>${label}</span><select name="${name}">${values.map(v=>{const [key,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(key)}" ${key===value?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`;
const check=(label,name,value=false)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}><span>${label}</span></label>`;
function toast(message,negative=false){const el=document.createElement('div');el.className='toast'+(negative?' negative':'');el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),6500)}
async function api(resource,action,options={}){const response=await fetch(`/api/${resource}?action=${action}`,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options});let data;try{data=await response.json()}catch{throw new Error('O servidor não respondeu corretamente. Tente novamente.')}if(!response.ok){const e=new Error(data.error||'Não foi possível concluir.');e.status=response.status;e.data=data;throw e}return data}
const auth=(action,payload)=>api('auth',action,payload===undefined?{}:{method:'POST',body:JSON.stringify(payload)});
const wa=(action,payload)=>api('whatsapp',action,payload===undefined?{}:{method:'POST',body:JSON.stringify(payload)});
const ai=(action,payload)=>api('ai',action,payload===undefined?{}:{method:'POST',body:JSON.stringify(payload)});
function saveStatus(){const el=$('#save-state');if(el){el.textContent=S.conflict?'Conflito de edição':S.error?'Falha ao salvar':S.saving?'Salvando…':S.dirty?'Alterações pendentes':'Salvo na nuvem';el.classList.toggle('has-error',!!(S.error||S.conflict))}const alert=$('#sync-error');if(alert){alert.hidden=!S.error&&!S.conflict;alert.querySelector('span').textContent=S.conflict?'A conta foi alterada em outra sessão. Baixe suas alterações antes de recarregar.':S.error}}
function changed(){S.dirty=true;mutationCount++;S.error='';clearTimeout(saveTimer);saveStatus();saveTimer=setTimeout(()=>flush().catch(()=>{}),550)}
async function flush(){clearTimeout(saveTimer);if(savePromise)await savePromise;if(!S.dirty||!S.account)return;if(S.conflict)throw new Error('Resolva o conflito antes de continuar.');const org=S.account.id,version=S.revision,count=mutationCount,payload=structuredClone(S.workspace);S.saving=true;saveStatus();savePromise=auth('workspace',{organization_id:org,revision:version,state:payload}).then(data=>{if(S.account?.id!==org)return;S.revision=data.revision;S.account=data.account||S.account;S.dirty=mutationCount!==count;S.error=''}).catch(error=>{if(S.account?.id===org){S.error=error.message;S.conflict=error.status===409;saveStatus();toast(error.status===409?'Outra sessão alterou esta conta. Suas alterações estão preservadas nesta tela.':error.message,true)}throw error}).finally(()=>{S.saving=false;savePromise=null;saveStatus()});await savePromise;if(S.dirty)return flush()}
function exportWorkspace(){const blob=new Blob([JSON.stringify(S.workspace,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pulseflow-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportLeadsCsv(){const blob=new Blob([leadsToCsv(S.workspace.leads)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pulseflow-contatos-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${S.workspace.leads.length} contatos preparados para exportação.`)}
async function importLeadsCsv(file){if(!permission('workspace_write'))throw new Error('Sua conta não permite importar contatos.');if(!file||file.size>2_000_000)throw new Error('Use um arquivo CSV de até 2 MB.');const result=parseLeadCsv(await file.text(),S.workspace);if(!result.leads.length)throw new Error(result.errors[0]||'Nenhum contato novo encontrado.');S.workspace.leads.push(...result.leads.map(lead=>({...lead,id:id()})));processDueReviews();changed();await flush();render();toast(`${result.leads.length} contatos importados${result.skipped?` · ${result.skipped} ignorados`:''}.`);if(result.errors.length)toast(result.errors[0],true)}
async function loadTeam(){if(!S.account||(!isAdmin()&&S.user?.role!=='owner')){S.team=null;return render()}try{S.team=await auth('team&organization_id='+encodeURIComponent(S.account.id))}catch(error){S.team={error:error.message,members:[],limit:1,plan:S.account.plan}}render()}
function teamPanel(){if(!isAdmin()&&S.user?.role!=='owner')return `<section class="panel"><h2>Segurança</h2><p>Troque sua senha sempre que precisar. As outras sessões serão encerradas.</p>${button('Alterar minha senha','password','secondary')}</section>`;
 const team=S.team,members=team?.members||[],active=members.filter(member=>member.status==='active').length,canAdd=team?.plan==='Equipe'&&active<(team?.limit||3)&&!S.support;
 return `<section class="panel"><div class="section-heading"><div><h2>Equipe</h2><p>Usuários reais que acessam o mesmo espaço da empresa.</p></div><span class="pill neutral">${active}/${team?.limit||1}</span></div>${team?.error?`<div class="notice">${esc(team.error)}</div>`:!team?'<p class="fine-print">Carregando equipe…</p>':`<div class="team-list">${members.map(member=>`<article><span class="avatar">${initials(member.name)}</span><div><b>${esc(member.name)}</b><small>${esc(member.email)} · ${member.role==='owner'?'Proprietário':'Vendedor'}</small></div><span class="pill ${member.status==='active'?'green':'amber'}">${member.status==='active'?'Ativo':'Suspenso'}</span>${member.role==='member'&&!S.support?`<button class="text-button" data-team-status="${member.status==='active'?'suspended':'active'}" data-team-user="${esc(member.id)}">${member.status==='active'?'Suspender':'Reativar'}</button>`:''}</article>`).join('')}</div>${canAdd?button(icon('plus')+' Adicionar vendedor','member','secondary'):team.plan==='Base'?'<div class="notice subtle">O plano Base é individual. O plano Equipe permite até 3 usuários ativos.</div>':'<p class="fine-print">Limite de usuários ativos atingido.</p>'}`}${!S.support?button('Alterar minha senha','password','text'):''}</section>`}
function downloadCalendar(leadId){const lead=S.workspace.leads.find(l=>l.id===leadId),task=lead&&taskList(S.workspace).find(x=>x.lead.id===leadId)?.task,event=calendarEvent(lead,task,S.account.name);if(!event)return toast('Agendamento não encontrado.',true);const blob=new Blob([event.ics],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pulseflow-'+String(lead.name||'contato').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'').toLowerCase()+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo de calendário preparado.')}
async function openWorkspace(org,support=false){await flush();const token=++S.loadToken;app.innerHTML=loading('Abrindo seu espaço…');const data=await auth('workspace&organization_id='+encodeURIComponent(org));if(token!==S.loadToken)return;S.workspace=normalizeWorkspace(data.workspace);S.account=data.account;S.revision=data.revision??0;S.support=support;S.team=null;S.remote=[];S.cursor='0';S.draft='';S.connection=null;S.aiStatus=null;S.aiAnalysis=null;S.search='';S.board='Principal';S.selected=S.workspace.leads[0]?.id;S.dirty=false;S.conflict=false;S.error='';S.page='home';if(processDueReviews()+processAutomations())changed();render();await Promise.all([refreshChannel(),refreshAIStatus()]);if(!S.workspace.businessProfile.onboarded&&!support)onboarding()}
const loading=text=>`<div class="loading"><div class="brand"><span class="logo">${icon('trend')}</span>pulseflow<span class="brand-dot">.</span></div><div class="loader"></div><p>${text}</p></div>`;
async function boot(){app.innerHTML=loading('Preparando o seu dia');try{const data=await auth('me');S.user=data.user;if(isAdmin()){S.page='admin';await loadAdmin()}else await openWorkspace(data.user.organization_id)}catch(e){login(e.status===401?'':'Não foi possível acessar o servidor. Tente entrar novamente.')}}
function login(error='',register=false){S.user=null;S.account=null;S.support=false;app.innerHTML=`<section class="auth-layout"><aside class="auth-story"><div class="brand light"><span class="logo">${icon('trend')}</span>pulseflow.</div><div><span class="eyebrow light">CADA CONVERSA MERECE CONTINUAR</span><h1>O próximo passo.<br>Na hora certa.</h1><p>Organize seus contatos, prepare mensagens com contexto e não deixe uma boa conversa se perder.</p><div class="auth-preview"><span class="avatar lilac">TD</span><div><b>Sua próxima oportunidade</b><small>Um contato. Uma ação. Um passo adiante.</small></div>${icon('check')}</div></div><small>Follow-up simples. Relações de verdade.</small></aside><div class="auth-side"><div class="auth-card"><span class="pill purple">7 dias para conhecer</span><h2>${register?'Comece uma boa conversa.':'Bom ter você de volta.'}</h2><p>${register?'Crie o espaço da sua empresa.':'Entre para continuar de onde parou.'}</p><form id="auth-form" data-register="${register}">${register?field('Seu nome','name','','required autocomplete="name" maxlength="100"')+field('Nome da empresa','company','','required maxlength="120"'):''}${field('E-mail','email','','type="email" required autocomplete="username" maxlength="254"')}${field('Senha','password','','type="password" required minlength="'+(register?'8':'1')+'" maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'"')}<p class="form-error" role="alert">${esc(error)}</p><button class="btn primary wide" type="submit">${register?'Criar minha conta':'Entrar no PulseFlow'} ${icon('arrow')}</button></form><p class="auth-switch">${register?'Já tem uma conta?':'Primeira vez aqui?'} <button class="text-button" data-auth-switch="${!register}">${register?'Entrar':'Criar conta'}</button></p><div class="auth-price">Base <b>R$ 9,90</b><span>/ mês</span><small>Organização e mensagens com aprovação manual.</small></div></div></div></section>`}
const primaryPages=[['home','home','Início'],['leads','leads','Contatos'],['conversations','chat','Conversas'],['agenda','calendar','Agenda'],['automations','spark','Automações']];
function shell(content){const nav=isAdmin()&&!S.support?[['admin','shield','Contas e usuários']]:primaryPages;const activeTitle=[...primaryPages,['settings','settings','Configurações'],['cadence','clock','Cadências'],['admin','shield','Administração']].find(p=>p[0]===S.page)?.[2]||'PulseFlow';return `<div class="app-shell ${S.menu?'menu-open':''}"><aside class="sidebar"><a class="brand" href="#home"><span class="logo">${icon('trend')}</span>pulseflow<span class="brand-dot">.</span></a><div class="workspace-label"><span class="workspace-icon">${initials(S.account?.name||'PulseFlow')}</span><div><b>${esc(S.account?.name||'Administração')}</b><small>${S.support?'Acesso de suporte':isAdmin()?'Administrador global':esc(S.account?.plan||'Base')+' · meu espaço'}</small></div></div><span class="nav-caption">MEU DIA A DIA</span><nav>${nav.map(([page,ic,label])=>`<button class="nav-item ${S.page===page?'active':''}" data-page="${page}">${icon(ic)}${label}${page==='agenda'&&todayTasks().length?`<span class="nav-count">${todayTasks().length}</span>`:''}${page==='automations'&&S.workspace.manualApprovals?.filter(a=>a.status==='pending').length?`<span class="nav-count">${S.workspace.manualApprovals.filter(a=>a.status==='pending').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom">${S.account?`<div class="mode-card"><i class="status-dot"></i><b>${S.connection?.ready?'WhatsApp oficial':'Você no controle'}</b><p>${S.connection?.ready?'Novas mensagens sincronizadas.':'Cada mensagem começa com a sua aprovação.'}</p>${button('Meu número '+icon('arrow'),'number','text')}</div><button class="nav-item ${S.page==='settings'?'active':''}" data-page="settings">${icon('settings')}Configurações</button>`:''}${S.support?button(icon('back')+' Voltar ao ADM','exit-support','text'):''}<div class="user-card"><span class="avatar">${initials(S.user.name)}</span><div><b>${esc(S.user.name)}</b><small>${isAdmin()?'Administrador':'Minha conta'}</small></div><button class="icon-button" data-action="logout" aria-label="Sair da conta">${icon('logout')}</button></div></div></aside><div class="main-shell">${S.support?`<div class="support-banner">${icon('shield')} Suporte · ${esc(S.account.name)}<span>Acessos e alterações registrados</span>${button('Voltar ao ADM','exit-support','text')}</div>`:''}<header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><span class="breadcrumb">Meu espaço <span>/</span> <b>${activeTitle}</b></span><div class="top-actions">${S.account?'<span id="save-state" class="cloud-status">Salvo na nuvem</span>':''}<span class="date-header">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span><span class="avatar small">${initials(S.user.name)}</span></div></header><div id="sync-error" class="sync-error" hidden role="alert"><span></span>${button('Tentar salvar','retry','text')}${button('Baixar cópia','export','text')}${button('Recarregar','reload-workspace','text')}</div><main class="page ${S.page==='conversations'?'chat-page':''}">${content}</main><nav class="mobile-nav">${nav.map(([page,ic,label])=>`<button class="${S.page===page?'active':''}" data-page="${page}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav></div></div>`}
function todayTasks(){const end=new Date();end.setHours(23,59,59,999);return taskList(S.workspace).filter(x=>x.task.at<=+end)}
function learnFromConversation(lead,body,direction='in'){
 if(!S.workspace.ai?.learningEnabled||!body||!lead)return;
 const text=String(body).trim().slice(0,500);if(!text)return;
 const lower=text.toLowerCase(),signals=[];
 if(/pre[cç]o|valor|or[cç]amento|caro|investimento/.test(lower))signals.push('investimento');
 if(/reuni[aã]o|agenda|hor[aá]rio|ligar|liga[cç][aã]o/.test(lower))signals.push('próximo passo');
 if(/d[uú]vida|como funciona|explica|entender/.test(lower))signals.push('dúvida');
 if(/agora|urgente|essa semana|hoje|amanh[aã]/.test(lower))signals.push('urgência');
 if(/n[aã]o quero|pare|remover|cancelar/.test(lower))signals.push('preferência de contato');
 const memory={id:id(),leadId:lead.id,leadName:lead.name,direction,at:new Date().toISOString(),signals,summary:text};
 S.workspace.ai.memories=[...(S.workspace.ai.memories||[]),memory].slice(-500);S.workspace.ai.lastLearnedAt=memory.at;
}
function automationMatches(rule,lead,reason,now=Date.now()){
 if(!rule.enabled||lead.optOut)return false;
 if(rule.board&&rule.board!=='Todos'&&rule.board!==lead.board)return false;
 if(reason==='reply_received')return rule.trigger==='reply_received';
 if(reason==='post_sale_signal')return rule.trigger==='post_sale_signal'&&lead.board==='Pós-venda';
 if(rule.trigger==='post_sale_signal')return false;
 if(rule.trigger==='stage_timeout'){const cols=lead.board==='Pós-venda'?S.workspace.postSaleColumns:S.workspace.columns,col=cols.find(c=>c.id===lead.stage),hours=Number(rule.delay||col?.limit||24);return lead.board!=='Pós-venda'&&canContact(lead)&&now-Number(lead.entered||now)>=hours*3600000}
 if(rule.trigger==='inactive_lead'){const hours=Number(rule.delay||720),last=new Date(lead.lastContactAt||lead.entered).getTime();return canContact(lead)&&now-last>=hours*3600000}
 return reason===rule.trigger;
}
function processAutomations(reason='scheduled',onlyLead=null){
 if(!S.workspace.ai?.enabled)return 0;let created=0;const now=Date.now(),day=new Date(now).toISOString().slice(0,10),leads=onlyLead?[onlyLead]:S.workspace.leads;
 for(const rule of S.workspace.automations||[])for(const lead of leads){if(!automationMatches(rule,lead,reason,now))continue;const runKey=`${rule.id}:${lead.id}:${day}`;if(S.workspace.automationRuns.some(r=>r.key===runKey))continue;const text=rule.action==='prepare_followup'?suggestions(S.workspace.businessProfile.customNiche||S.workspace.businessProfile.niche,lead)[1]:'';S.workspace.automationRuns.push({key:runKey,ruleId:rule.id,leadId:lead.id,at:new Date(now).toISOString()});S.workspace.manualApprovals.unshift({id:id(),ruleId:rule.id,leadId:lead.id,leadName:lead.name,status:'pending',createdAt:new Date(now).toISOString(),title:rule.name,summary:rule.instructions||'Revise o contexto e decida o próximo passo.',text});created++}
 S.workspace.automationRuns=S.workspace.automationRuns.slice(-1000);return created;
}
function processDueReviews(now=Date.now()){
 if(!S.account||!permission('workspace_write'))return 0;
 const existing=new Set((S.workspace.manualApprovals||[]).map(a=>a.dedupeKey).filter(Boolean));let created=0;
 for(const action of dueReviewActions(S.workspace,now)){if(existing.has(action.dedupeKey))continue;S.workspace.manualApprovals.unshift({id:id(),...action,status:'pending',createdAt:new Date(now).toISOString()});existing.add(action.dedupeKey);created++}
 S.workspace.manualApprovals=S.workspace.manualApprovals.slice(0,2000);return created;
}
function leadAction(item){S.selected=item.id;S.page='conversations';S.draft='';render()}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
function taskRow({lead:l,task}){return `<div class="task-row"><span class="task-icon ${task.type==='Ligação'?'lilac':'peach'}">${icon(task.type==='Ligação'?'phone':'chat')}</span><div class="task-copy"><b>${esc(l.name)}</b><span>${esc(task.type)} <i>·</i> ${esc(l.product||l.origin||'Contato')}</span></div><span class="due ${task.at<Date.now()?'late':''}">${task.at<Date.now()?'Pendente':dateTime(task.at)}</span><button class="icon-button" data-open="${esc(l.id)}" aria-label="Abrir ${esc(l.name)}">${icon('arrow')}</button></div>`}
function home(){const w=S.workspace,tasks=todayTasks(),next=taskList(w)[0],niche=w.businessProfile.customNiche||w.businessProfile.niche||'seu negócio',list=suggestions(niche),closed=w.leads.filter(l=>l.stage==='closed'),completed=w.reminders.filter(r=>r.done&&new Date(r.completedAt).toDateString()===new Date().toDateString()).length;return heading('MENOS ESFORÇO. MAIS CONTINUIDADE.',`Olá, ${esc(S.user.name.split(' ')[0])}<span class="greeting-dot">.</span>`,tasks.length?`Você tem ${tasks.length} ${tasks.length===1?'próximo passo':'próximos passos'} para hoje. Vamos por partes.`:'Seu dia está organizado. Abra espaço para a próxima conversa.',button(icon('plus')+' Novo contato','lead','primary'))+(!w.whatsapp.number?`<div class="onboarding-strip"><span class="round-icon">${icon('phone')}</span><div><b>Seu negócio, pronto para começar.</b><p>Cadastre seu número e personalize suas sugestões.</p></div>${button('Configurar meu espaço '+icon('arrow'),'onboarding','secondary')}</div>`:'')+`<section class="metrics"><article><span>${icon('leads')} Contatos ativos</span><b>${w.leads.filter(canContact).length}</b><small>Relacionamentos em andamento</small></article><article><span>${icon('clock')} Para hoje</span><b>${tasks.length.toString().padStart(2,'0')}</b><small>Próximas ações organizadas</small></article><article><span>${icon('check')} Vendas fechadas</span><b>${closed.length.toString().padStart(2,'0')}</b><small>${money(closed.reduce((a,l)=>a+Number(l.contractValue||0),0))} em contratos</small></article><article><span>${icon('calendar')} Concluídas hoje</span><b>${completed.toString().padStart(2,'0')}</b><small>Cada passo conta</small></article></section><div class="home-grid"><div class="home-main"><section class="next-card"><div class="next-copy"><span class="eyebrow">${icon('spark')} SEU PRÓXIMO PASSO</span><h2>${next?`${next.task.type==='Ligação'?'Uma ligação para':'Retome com'}<br>${esc(next.lead.name)}.`:'Seu próximo capítulo<br>começa aqui.'}</h2><p>${next?esc(next.lead.needs||next.lead.last||'Entenda o momento do cliente e combine um próximo passo.'):'Adicione um contato e deixe o PulseFlow organizar o acompanhamento com você.'}</p>${next?`<button class="btn dark" data-open="${next.lead.id}">${next.task.type==='Ligação'?'Preparar ligação':'Abrir conversa'} ${icon('arrow')}</button>`:button((w.leads.length?'Adicionar contato ':'Adicionar primeiro contato ')+icon('arrow'),'lead','dark')}</div><div class="next-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="floating-message"><span class="avatar">${next?initials(next.lead.name):'P'}</span><span><i></i><i></i></span><em>${icon('check')}</em></div><div class="floating-note">${icon('clock')} No seu tempo. Com contexto.</div><div class="art-star">✦</div></div></section><section class="panel priorities"><div class="section-heading"><div><h2>O que merece sua atenção</h2><p>Uma conversa de cada vez.</p></div><button class="text-button" data-page="agenda">Ver agenda ${icon('arrow')}</button></div>${tasks.slice(0,5).map(taskRow).join('')||empty('Tudo em dia por aqui','Seus agendamentos e acompanhamentos aparecerão nesta lista.',null)}</section></div><aside class="home-aside"><section class="panel rhythm"><div class="section-heading"><h2>Seu ritmo</h2><span class="pill neutral">7 dias</span></div><div class="week-bars">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const count=w.reminders.filter(r=>r.done&&new Date(r.completedAt).toDateString()===d.toDateString()).length+w.leads.reduce((a,l)=>a+0,0);return `<div><span>${count||''}</span><i style="height:${Math.max(7,Math.min(80,count*15))}px" class="${i===6?'current':''}"></i><small>${d.toLocaleDateString('pt-BR',{weekday:'short'}).slice(0,3)}</small></div>`}).join('')}</div><p>Consistência constrói boas conversas.</p></section><section class="panel niche-panel"><span class="eyebrow">${icon('spark')} UMA IDEIA PARA COMEÇAR</span><h2>Feito para ${esc(niche)}.</h2><p>${esc(list[0].replace('{nome}','cliente'))}</p>${button('Usar essa sugestão '+icon('arrow'),'suggest-first','text')}<div class="niche-footer">Templates prontos · sem custo de IA<button class="text-button" data-action="onboarding">Personalizar</button></div></section></aside></div>`}
function leads(){const w=S.workspace,columns=S.board==='Pós-venda'?w.postSaleColumns:w.columns,items=w.leads.filter(l=>l.board===S.board&&(l.name+' '+l.phone+' '+l.origin).toLowerCase().includes(S.search.toLowerCase()));return heading('SEUS RELACIONAMENTOS','Cada contato, um próximo passo.','Arraste entre etapas ou use o menu do contato para mover.',button(icon('plus')+' Novo contato','lead','primary'))+`<div class="toolbar"><div class="segmented board-tabs">${BOARDS.map(b=>`<button class="${S.board===b?'active':''}" data-board="${b}">${b}</button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="lead-search" aria-label="Buscar contatos" placeholder="Buscar contato…" value="${esc(S.search)}"></label></div>${S.board==='Pós-venda'?'<div class="notice">Pós-venda: acompanhamento e notas. Mensagens operacionais permanecem desativadas.</div>':''}<div class="board">${columns.map((c,i)=>`<section class="kanban-column" data-column="${esc(c.id)}"><header><h2><i class="column-dot dot-${i%4}"></i>${esc(c.name)}<span>${items.filter(l=>l.stage===c.id).length}</span></h2><button class="icon-button" data-config-column="${esc(c.id)}" aria-label="Configurar ${esc(c.name)}">${icon('settings')}</button></header><p class="column-sla">${c.limit?`Revisar em até ${c.limit}h`:'Sem prazo limite'}</p><div class="kanban-list">${items.filter(l=>l.stage===c.id).map(l=>`<article class="lead-card" draggable="true" data-drag="${esc(l.id)}"><div class="lead-card-top"><span class="avatar ${['lilac','peach','mint','blue'][i%4]}">${initials(l.name)}</span><button class="text-button lead-name" data-open="${esc(l.id)}">${esc(l.name)}</button><span class="interest ${l.interest==='Alta'?'high':''}">${esc(l.interest||'Média')}</span></div><p class="lead-phone">${esc(l.phone)}</p><p class="lead-snippet">${esc(l.last||l.needs||'Pronto para o primeiro contato')}</p><div class="tags"><span class="pill neutral">${esc(l.origin||'Não informado')}</span>${l.optOut?'<span class="pill amber">Não contatar</span>':''}${l.product?`<span class="pill purple">${esc(l.product)}</span>`:''}</div><div class="lead-card-bottom"><span class="${c.limit&&Date.now()-l.entered>c.limit*3600000?'late':''}">${icon('clock')} ${elapsed(l.entered)} na etapa</span><button class="icon-button" data-notes="${esc(l.id)}" aria-label="Notas e contrato de ${esc(l.name)}">${icon('notes')}</button></div></article>`).join('')||'<div class="column-empty">Um espaço para novas oportunidades</div>'}</div></section>`).join('')}<button class="add-column" data-action="column">${icon('plus')} Nova etapa</button></div>`}
function chatMessages(l){const remote=S.remote.filter(m=>phoneNumber(m.contact_phone)===phoneNumber(l.phone));return [...l.messages.map(messageData),...remote].map(m=>`<div class="message ${m.direction==='in'?'incoming':'outgoing'}"><p>${esc(m.body||'['+(m.message_type||'mídia')+']')}</p><small>${esc(m.time||dateTime(m.occurred_at||m.at))} · ${esc(({accepted:'Aceita pela Meta',sent:'Enviada pela Meta',delivered:'Entregue',read:'Lida',received:'Recebida',confirmed_manual:'Envio confirmado por você'})[m.status]||m.status||'Registro manual')}</small></div>`).join('')||'<div class="chat-empty">'+icon('chat')+'<h3>A conversa começa com contexto.</h3><p>Mensagens confirmadas ou recebidas pela integração oficial aparecem aqui.</p></div>'}
function conversations(){const l=currentLead();if(!l)return heading('CONVERSAS','Um espaço para continuar.','Seus contatos e o contexto de cada conversa, juntos.')+empty('Sua primeira conversa está por vir','Cadastre um contato para começar.');S.selected=l.id;const tips=contextualTips(l);return `<div class="chat-layout"><aside class="chat-contacts"><div class="chat-list-head"><h2>Conversas <span>${S.workspace.leads.length}</span></h2><button class="icon-button" data-action="lead" aria-label="Adicionar contato">${icon('plus')}</button></div><label class="searchbox">${icon('search')}<input id="chat-search" placeholder="Buscar conversa…" aria-label="Buscar conversa"></label><div class="conversation-items">${S.workspace.leads.map(item=>`<button class="conversation-item ${l.id===item.id?'active':''}" data-open="${esc(item.id)}"><span class="avatar lilac">${initials(item.name)}</span><span><b>${esc(item.name)}</b><small>${esc(item.last||item.origin||'Nova conversa')}</small></span></button>`).join('')}</div></aside><section class="chat-thread"><header class="chat-header"><span class="avatar mint">${initials(l.name)}</span><div><h2>${esc(l.name)}</h2><p>${esc(l.phone)} <span>· ${S.connection?.ready?'API oficial':'Acompanhamento manual'}</span></p></div><button class="icon-button" data-notes="${esc(l.id)}" aria-label="Editar contato">${icon('notes')}</button></header><div class="chat-mode">${icon('shield')} ${S.connection?.ready?'Cada envio precisa da sua aprovação.':'O WhatsApp abre para você enviar. O histórico é confirmado por você.'}</div><div class="messages" id="messages">${chatMessages(l)}</div>${l.pendingManual?`<div class="manual-confirm"><b>Você enviou a mensagem no WhatsApp?</b><span>Abrir a conversa não confirma o envio.</span>${button('Sim, registrar envio','confirm-manual','primary')}${button('Ainda não','cancel-manual','text')}</div>`:''}${!canContact(l)?'<div class="notice">Envio pausado para este contato. Confira a etapa e a preferência de contato nas notas.</div>':`<div class="quick-replies">${['Primeiro contato','Follow-up','Próximo passo'].map((t,i)=>`<button data-template="${i}" type="button">${icon('spark')}${t}</button>`).join('')}${button(icon('clock')+' Cadência','lead-cadence','text')}</div>${!callRecorded(l)?`<div class="call-rule">${icon('phone')} Primeiro, registre uma tentativa de ligação. ${button('Registrar ligação','call','text')}</div>`:''}<form id="composer" class="composer"><textarea id="message-input" name="text" aria-label="Mensagem" placeholder="Uma mensagem com contexto faz a diferença…" maxlength="4000" ${!callRecorded(l)?'disabled':''}>${esc(S.draft)}</textarea><div><span>Revise antes de enviar.</span><button class="btn primary" type="submit" ${!callRecorded(l)||!permission('workspace_write')||(S.connection?.ready&&!permission('whatsapp_send'))?'disabled':''}>${S.connection?.ready?'Aprovar e enviar':'Abrir no WhatsApp'} ${icon('arrow')}</button></div></form>`}</section><aside class="chat-context"><div class="context-tabs"><button class="${S.chatTab==='tips'?'active':''}" data-chat-tab="tips">${icon('spark')} Dicas</button><button class="${S.chatTab==='notes'?'active':''}" data-chat-tab="notes">${icon('notes')} Notas</button></div>${S.chatTab==='tips'?`<span class="eyebrow">CONTEXTO, ANTES DE TUDO</span><h3>Um bom próximo passo.</h3><div class="tip-list">${tips.map((t,i)=>`<article><span>0${i+1}</span><p>${esc(t)}</p></article>`).join('')}</div><p class="fine-print">Sugestões por regras e templates, baseadas nos registros disponíveis. Nenhuma IA conectada.</p>`:`<h3>O que vale lembrar</h3><p class="notes-copy">${esc(l.notes||'Registre necessidade, objeção e o que ficou combinado.')}</p>${button('Editar notas e contrato','notes','secondary')}<dl><dt>Necessidade</dt><dd>${esc(l.needs||'Ainda não registrada')}</dd><dt>Produto / contrato</dt><dd>${esc(l.product||'Não informado')} · ${money(l.contractValue)}</dd></dl>`}<div class="context-next"><h3>${icon('calendar')} Próximo contato</h3><p>${l.nextDate?dateTime(l.nextDate):'Combine o melhor momento.'}</p>${button('Agendar próximo passo','schedule','secondary wide')}${button('Registrar ligação','call','text wide')}</div></aside></div>`}
function agenda(){const tasks=taskList(S.workspace),end=new Date();end.setHours(23,59,59,999);const done=S.workspace.reminders.filter(r=>r.done),list=S.agenda==='upcoming'?tasks.filter(x=>x.task.at>+end):tasks.filter(x=>x.task.at<=+end);return heading('NO TEMPO CERTO','Sua agenda, sem pontas soltas.','Organizamos os prazos. Você decide a hora de conversar.',button(icon('plus')+' Agendar contato','schedule-select','primary'))+`<div class="segmented agenda-tabs">${[['today','Hoje',todayTasks().length],['upcoming','Próximos',tasks.filter(x=>x.task.at>+end).length],['done','Concluídos',done.length]].map(([k,label,n])=>`<button class="${S.agenda===k?'active':''}" data-agenda="${k}">${label}<span>${n}</span></button>`).join('')}</div><section class="panel agenda-list">${S.agenda==='done'?done.map(r=>`<div class="task-row"><span class="task-icon mint">${icon('check')}</span><div class="task-copy"><b>${esc(r.title)}</b><span>${dateTime(r.completedAt)}</span></div></div>`).join('')||empty('Ainda sem ações concluídas','As ações que você concluir ficam registradas aqui.',null):list.map(x=>{const event=calendarEvent(x.lead,x.task,S.account.name);return `<div class="agenda-entry">${taskRow(x)}<div class="agenda-actions"><a class="text-button" href="${esc(event.url)}" target="_blank" rel="noopener noreferrer">Google Agenda</a><button class="text-button" data-calendar="${x.lead.id}">Baixar .ics</button><button class="text-button" data-schedule="${x.lead.id}">Reagendar</button><button class="text-button" data-complete="${x.lead.id}">${icon('check')} Concluir</button></div></div>`}).join('')||empty('Tudo organizado','Nenhuma ação neste período.',null)}</section><p class="fine-print">Enquanto o PulseFlow está aberto, os horários vencidos entram automaticamente em “Aguardando sua decisão”. Com a plataforma fechada, o agendador diário recupera as pendências. Nenhuma mensagem é enviada sozinha.</p>`}
function alertItems(){const now=Date.now(),replies=(S.workspace.notifications||[]).map(n=>({id:n.id,leadId:n.leadId,title:n.text||'Nova resposta recebida',detail:n.at?dateTime(n.at):'Agora',at:+new Date(n.at||now),unread:!n.readAt,type:'reply'})),overdue=taskList(S.workspace,now).filter(x=>x.task.at<now).map(x=>({id:'due-'+x.lead.id,leadId:x.lead.id,title:'Ação pendente · '+x.lead.name,detail:x.task.type+' deveria ter sido feita '+dateTime(x.task.at),at:x.task.at,unread:true,type:'due'}));return [...replies,...overdue].sort((a,b)=>b.at-a.at).slice(0,50)}
function renderAlerts(){if(!S.account)return;const host=$('.top-actions'),items=alertItems(),unread=items.filter(x=>x.unread).length;if(!host)return;host.insertAdjacentHTML('afterbegin',`<button class="alert-button ${unread?'has-alerts':''}" data-alerts aria-label="Abrir alertas">${icon('clock')}${unread?`<span>${Math.min(99,unread)}</span>`:''}</button>`)}
function alertCenter(){const items=alertItems();for(const n of S.workspace.notifications||[])if(!n.readAt)n.readAt=new Date().toISOString();if(S.workspace.notifications?.length)changed();dialog('Alertas e próximas ações',`<p class="modal-description">Respostas recebidas e ações vencidas ficam aqui até você cuidar delas.</p><div class="alert-list">${items.map(item=>`<button type="button" data-alert-lead="${esc(item.leadId)}"><span class="task-icon ${item.type==='reply'?'mint':'peach'}">${icon(item.type==='reply'?'chat':'clock')}</span><span><b>${esc(item.title)}</b><small>${esc(item.detail)}</small></span>${icon('arrow')}</button>`).join('')||empty('Tudo em dia','Nenhum alerta precisa da sua atenção agora.',null)}</div><footer class="modal-actions">${button('Fechar','close','secondary','type="button"')}</footer>`,'wide-modal')}
function automations(){const w=S.workspace,ai=w.ai||{},pending=w.manualApprovals.filter(a=>a.status==='pending'),memories=[...(ai.memories||[])].reverse().slice(0,8);return heading('AUTOMAÇÕES COM CONTROLE','Seu agente, suas regras.','Configure o acompanhamento de cada empresa sem misturar dados entre clientes.',button(icon('plus')+' Nova automação','automation-rule','primary'))+`<section class="automation-hero"><div><span class="eyebrow">AGENTE DESTA EMPRESA</span><h2>${esc(ai.name||'Agente PulseFlow')}</h2><p>${esc(ai.goal||'Ajude o vendedor a manter o próximo passo claro.')}</p><div class="agent-state"><i class="status-dot ${ai.enabled?'on':''}"></i>${ai.enabled?'Agente ativo':'Agente pausado'} · ${esc(ai.tone||'Consultivo')}</div></div><div class="automation-stats"><article><b>${w.automations.filter(a=>a.enabled).length}</b><span>regras ativas</span></article><article><b>${pending.length}</b><span>ações para revisar</span></article><article><b>${ai.memories?.length||0}</b><span>registros aprendidos</span></article></div></section><div class="automation-grid"><div><section class="panel"><div class="section-heading"><div><h2>Configurar agente</h2><p>Essa configuração vale somente para ${esc(S.account.name)}.</p></div><span class="pill ${ai.enabled?'green':'neutral'}">${ai.enabled?'Ativo':'Pausado'}</span></div><form id="agent-form">${check('Ativar o agente para preparar ações e sugestões','enabled',ai.enabled)}${field('Nome do agente','name',ai.name,'required maxlength="80"')}${textarea('Objetivo principal','goal',ai.goal,'required maxlength="1000"')}${select('Tom de voz','tone',['Consultivo e direto','Acolhedor e simples','Objetivo e comercial','Técnico e educativo'],ai.tone||'Consultivo e direto')}${textarea('O que a IA observadora deve identificar','observerInstructions',ai.observerInstructions,'maxlength="2000"')}${textarea('Como a IA operacional deve ajudar','operatorInstructions',ai.operatorInstructions,'maxlength="2000"')}${check('Aprender continuamente com conversas e ligações desta empresa','learningEnabled',ai.learningEnabled)}${field('Guardar memória por (dias)','memoryRetentionDays',ai.memoryRetentionDays||180,'type="number" min="7" max="730" required')}<div class="notice subtle">Modo seguro: o agente prepara sugestões, tarefas e alertas. Nenhuma mensagem é enviada sem autorização do vendedor.</div><button class="btn primary" type="submit">Salvar agente</button></form></section><section class="panel spaced"><div class="section-heading"><div><h2>Regras de automação</h2><p>Personalizadas para esta empresa.</p></div></div><div class="automation-rules">${w.automations.map(r=>`<article><span class="task-icon ${r.enabled?'mint':'lilac'}">${icon(r.action==='observe_only'?'search':'spark')}</span><div><b>${esc(r.name)}</b><small>${esc(({stage_timeout:'Quando o prazo da etapa vencer',reply_received:'Quando o cliente responder',inactive_lead:'Quando o contato ficar inativo',post_sale_signal:'Ao identificar sinal no pós-venda'})[r.trigger]||r.trigger)} · ${esc(r.board||'Todos')}</small></div><button class="text-button" data-edit-automation="${esc(r.id)}">Editar</button><button class="text-button" data-toggle-automation="${esc(r.id)}">${r.enabled?'Pausar':'Ativar'}</button></article>`).join('')||empty('Nenhuma regra criada','Crie a primeira automação desta empresa.',null)}</div></section></div><aside><section class="panel"><div class="section-heading"><div><h2>Aguardando sua decisão</h2><p>O agente prepara. Você decide.</p></div><span class="pill amber">${pending.length}</span></div><div class="approval-list">${pending.slice(0,8).map(a=>`<article><b>${esc(a.leadName||'Contato')}</b><span>${esc(a.title)}</span><p>${esc(a.summary)}</p>${a.text?`<em>“${esc(a.text)}”</em>`:''}<div><button class="btn secondary" data-review-automation="${esc(a.id)}">Revisar conversa</button><button class="text-button" data-dismiss-automation="${esc(a.id)}">Descartar</button></div></article>`).join('')||'<p class="fine-print">Nenhuma ação pendente. Novas sugestões aparecerão aqui.</p>'}</div></section><section class="panel spaced"><div class="section-heading"><div><h2>Memória da empresa</h2><p>Sinais usados para melhorar as próximas sugestões.</p></div></div>${memories.map(m=>`<article class="memory-item"><b>${esc(m.leadName||'Contato')}</b><span>${m.signals?.length?m.signals.map(x=>`<i>${esc(x)}</i>`).join(''):'contexto registrado'}</span><p>${esc(m.summary)}</p><small>${dateTime(m.at)}</small></article>`).join('')||'<p class="fine-print">A memória começará quando houver conversas ou ligações registradas.</p>'}<p class="fine-print">Memórias são isoladas por empresa e não treinam um modelo global. A conexão com um modelo de IA será feita no servidor, sem expor chaves aos clientes.</p></section></aside></div>`}
function settings(){const w=S.workspace;return heading('SEU ESPAÇO','Do seu jeito.','O essencial fica à mão. Os detalhes técnicos ficam aqui.')+`<div class="settings-layout"><nav class="settings-nav">${[['business','Meu negócio'],['channel','WhatsApp e integrações'],['operation','Regras e cadências'],['plan','Plano'],['security','Conta e dados']].map(([k,t])=>`<button class="${S.settingsTab===k?'active':''}" data-settings="${k}">${t}</button>`).join('')}</nav><div class="settings-content">${S.settingsTab==='business'?`<section class="panel"><h2>Meu negócio</h2><p>Templates que falam a língua de quem você atende.</p><form id="business-form">${field('Nome da empresa','businessName',w.whatsapp.businessName||S.account.name,'required maxlength="120"')}${select('Nicho','niche',[...NICHES,'Outro'],w.businessProfile.customNiche?'Outro':w.businessProfile.niche||'Serviços')}${field('Seu nicho','customNiche',w.businessProfile.customNiche,'maxlength="100"')}${field('Seu WhatsApp com DDD','number',w.whatsapp.number,'type="tel" autocomplete="tel" placeholder="(11) 99999-9999"')}${button('Salvar meu negócio','submit-business','primary','type="submit"')}</form></section>`:S.settingsTab==='channel'?channelSettings():S.settingsTab==='operation'?`<section class="panel"><h2>Regras de acompanhamento</h2><p>Os prazos viram próximas ações. Cada mensagem exige uma decisão sua.</p><form id="rules-form">${field('Retomar contatos inativos após (dias)','inactiveDays',w.settings.inactiveDays,'type="number" min="1" max="365" required')}${field('Prazo padrão de recuperação (dias)','recoveryDays',w.settings.recoveryDays,'type="number" min="1" max="730" required')}<div class="notice">A ligação inicial é obrigatória. Pedidos para não receber contato pausam o acompanhamento.</div><button class="btn primary" type="submit">Salvar regras</button></form></section><section class="panel"><h2>Cadências e etapas</h2><p>Ajuste mensagens, horas, dias e o tempo máximo em cada etapa.</p>${button('Editar cadência de mensagens','cadence','secondary')}${button('Configurar etapas do pipeline','pipeline-settings','text')}</section><section class="panel"><h2>Automações em área própria</h2><p>Agentes, memória e regras personalizadas agora ficam separados das configurações técnicas.</p><button class="btn secondary" type="button" data-page="automations">Abrir Automações ${icon('arrow')}</button></section>`:S.settingsTab==='plan'?`<div class="plans">${[['Base','9,90','Uma operação simples e organizada'],['Equipe','29,90','Mais pessoas no acompanhamento']].map(([name,price,desc])=>`<section class="panel plan ${S.account.plan===name?'selected':''}"><span class="pill ${S.account.plan===name?'purple':'neutral'}">${S.account.plan===name?'Seu plano':'Plano da plataforma'}</span><h2>${name}</h2><p>${desc}</p><div class="plan-price">R$ ${price}<small>/ mês</small></div><ul><li>Contatos, notas e contratos</li><li>Agenda e cadências configuráveis</li><li>Templates por nicho</li><li>Aprovação antes de cada envio</li></ul></section>`).join('')}</div><div class="notice">A cobrança online ainda não está conectada. Alterações de plano são administradas pelo responsável da plataforma. O consumo da API WhatsApp é pago pelo cliente ao provedor; o PulseFlow não cobra mensalidade da API.</div>`:`<section class="panel"><h2>Sua conta</h2><dl><dt>Nome</dt><dd>${esc(S.user.name)}</dd><dt>E-mail</dt><dd>${esc(S.user.email)}</dd><dt>Empresa</dt><dd>${esc(S.account.name)}</dd></dl>${button('Baixar meus dados','export','secondary')}${button('Sair da conta','logout','text')}<p class="fine-print">Cadastro, contas e dados operacionais são armazenados no banco da plataforma. Tokens de integração são tratados somente pelo servidor.</p></section>${teamPanel()}<section class="panel"><h2>Integração com outros sistemas</h2><p>Leve seus contatos para outro CRM ou traga uma lista existente sem misturar contas.</p><div class="integration-actions">${button('Exportar contatos CSV','export-leads','secondary')}<label class="btn secondary" for="crm-import">Importar contatos CSV</label><input id="crm-import" type="file" accept=".csv,text/csv" hidden></div><p class="fine-print">Colunas aceitas: nome, WhatsApp, origem, interesse, pipeline, etapa, produto, valor do contrato, nicho, faturamento, necessidade e notas. Contatos duplicados são ignorados e nenhum contato importado recebe autorização automática de mensagem.</p></section>`}</div></div>`}
function channelSettings(){const c=S.connection||{},s=c.setup||{server_ready:c.encryption_ready===true,credentials_saved:!!c.configured,meta_verified:!!c.connection?.meta_verified_at,webhook_verified:!!c.connection?.webhook_verified_at};const steps=[['Servidor protegido',s.server_ready,'A chave protege os tokens de cada empresa.'],['Credenciais da Meta',s.credentials_saved,'Phone Number ID, conta comercial e tokens salvos.'],['Número validado',s.meta_verified,'A Meta confirmou que o número pertence à conta.'],['Webhook ativo',s.webhook_verified,'Novas mensagens e confirmações chegam ao PulseFlow.']];return `${c.error?`<div class="notice" role="alert">Não foi possível verificar a integração: ${esc(c.error)}</div>`:''}${c.warning?`<div class="notice" role="alert">${esc(c.warning)}</div>`:''}<section class="panel"><div class="section-heading"><div><h2>Seu WhatsApp</h2><p>Use o modo manual agora ou conclua a conexão oficial.</p></div><span class="pill ${c.ready?'green':'neutral'}">${c.ready?'Oficial conectado':c.configured?'Configuração pendente':'Modo manual'}</span></div><div class="number-card">${icon('phone')}<div><b>${esc(S.workspace.whatsapp.number||'Cadastre seu número')}</b><span>${c.ready?'Sincronização oficial de novas mensagens':'Número cadastrado; envio manual disponível'}</span></div>${button('Editar','number','secondary')}</div><ol class="connection-checklist">${steps.map(([title,done,description],index)=>`<li class="${done?'done':''}"><span>${done?icon('check'):index+1}</span><div><b>${title}</b><small>${description}</small></div></li>`).join('')}</ol><details class="advanced" ${c.configured||c.webhook_prepared?'open':''}><summary>Configuração avançada da API oficial</summary><p>Você pode validar o webhook agora e conectar o número depois.</p>${s.server_ready!==true?'<div class="notice">Falta configurar a chave de criptografia no servidor. Por segurança, os tokens ficam bloqueados até essa etapa.</div>':''}${!c.configured?`<form id="webhook-form">${field('Crie um token de verificação','verify_token','','type="password" required minlength="20" maxlength="512" autocomplete="new-password" placeholder="Mínimo de 20 caracteres"')}<div class="notice subtle">Use o mesmo token no campo “Verificar token” da Meta.</div><button class="btn secondary" ${s.server_ready!==true||!permission('whatsapp_manage')?'disabled':''}>Preparar webhook</button></form>`:''}<form id="whatsapp-form">${field('Phone Number ID','phone_number_id',c.connection?.phone_number_id||'','required inputmode="numeric"')}${field('WhatsApp Business Account ID','waba_id',c.connection?.waba_id||'','required inputmode="numeric"')}${field('Versão da Graph API','graph_version',c.connection?.graph_version||'v23.0','required pattern="v[0-9]+\\.[0-9]+"')}${field('Token da Meta','access_token','','type="password" required autocomplete="new-password"')}${field('App Secret','app_secret','','type="password" required autocomplete="new-password"')}${field('Mesmo token de verificação','verify_token','','type="password" required minlength="20" maxlength="512" autocomplete="new-password" placeholder="Use o mesmo token validado no webhook"')}<button class="btn primary" ${s.server_ready!==true||!permission('whatsapp_manage')?'disabled':''}>Salvar credenciais e validar número</button></form>${c.webhook_url?`<div class="copy-field"><span>URL de retorno (Callback URL)</span><div><input id="saved-webhook-url" readonly value="${esc(c.webhook_url)}"><button type="button" class="btn secondary" data-copy="saved-webhook-url">Copiar</button></div></div>${c.configured?button('Testar credenciais novamente','validate-wa','secondary'):''}`:''}<p class="fine-print">A versão oficial sincroniza somente novas conversas individuais. Não importa histórico antigo nem grupos.</p></details></section><section class="panel"><h2>Outras integrações</h2><p>Os agendamentos e registros locais já ajudam a organizar o acompanhamento.</p>${[['Google Agenda','Reuniões e compromissos'],['VoIP','Registro de ligações'],['CRM externo','Seu cadastro de referência']].map(([t,d])=>`<div class="integration-row"><span class="task-icon lilac">${icon('settings')}</span><div><b>${t}</b><p>${d}</p></div><span class="pill neutral">Não conectado</span></div>`).join('')}<p class="fine-print">Esses conectores ainda precisam de implementação e autorização do provedor. Nenhuma conexão é simulada.</p></section>`}
function cadence(){return heading('CONTINUIDADE COM CONTEXTO','Sua sequência de acompanhamento.','Prazos contados a partir da ativação no contato. Cada etapa prepara uma ação manual.',button(icon('back')+' Voltar às configurações','back-settings','secondary'))+`<div class="notice">Primeira etapa: registrar uma ligação. Você pode personalizar os modelos e pausar a sequência a qualquer momento.</div><form id="cadence-form" class="cadence-form">${S.workspace.cadence.map((step,i)=>`<article class="panel cadence-step"><span class="step-index">${String(i+1).padStart(2,'0')}</span><div>${field('Após','delay-'+i,step.delay,'type="number" min="0" max="17520" required')}${select('Unidade','unit-'+i,['horas','dias'],/dia/.test(step.unit)?'dias':'horas')}</div>${textarea(step.action==='Ligar'?'Orientação da ligação':'Mensagem','text-'+i,step.text,'required maxlength="4000"')}<button class="icon-button" type="button" data-remove-step="${i}" aria-label="Remover etapa ${i+1}">${icon('close')}</button></article>`).join('')}<div class="form-actions">${button(icon('plus')+' Adicionar etapa','add-step','secondary','type="button"')}<button class="btn primary">Salvar cadência</button></div></form>`}
async function loadAdmin(){const token=++S.loadToken;S.admin=await auth('admin');if(token===S.loadToken){S.page='admin';render()}}
function admin(){const a=S.admin||{accounts:[],users:[],audits:[],summary:{}};return heading('ADMINISTRAÇÃO','Um olhar sobre toda a plataforma.','Contas, acesso de suporte e alterações registradas.',button('Atualizar','refresh-admin','secondary'))+`<section class="metrics admin-metrics">${[['Empresas',a.summary.accounts],['Usuários',a.summary.users],['Usuários ativos',a.summary.active]].map(([t,n])=>`<article><span>${t}</span><b>${n||0}</b></article>`).join('')}</section><section class="panel"><div class="section-heading"><h2>Contas dos clientes</h2><span class="pill neutral">${a.accounts.length} empresas</span></div><div class="table-scroll"><table><thead><tr><th>Empresa</th><th>Plano</th><th>Usuários</th><th>Status</th><th>Acesso</th></tr></thead><tbody>${a.accounts.map(o=>`<tr><td><b>${esc(o.name)}</b><small>${esc(o.niche||'Nicho ainda não informado')}</small></td><td>${esc(o.plan)}</td><td>${o.users_count}</td><td><span class="pill ${o.status==='active'?'green':'amber'}">${o.status==='active'?'Ativa':'Suspensa'}</span></td><td><div class="table-actions"><button class="btn secondary" data-support="${esc(o.id)}">Acessar ambiente</button><button class="text-button" data-manage-account="${esc(o.id)}">Gerenciar</button></div></td></tr>`).join('')||'<tr><td colspan="5">Nenhuma empresa cadastrada.</td></tr>'}</tbody></table></div></section><section class="panel spaced"><h2>Todos os usuários</h2><div class="table-scroll"><table><thead><tr><th>Pessoa</th><th>Empresa</th><th>Perfil</th><th>Último acesso</th><th>Status</th></tr></thead><tbody>${a.users.map(u=>`<tr><td><b>${esc(u.name)}</b><small>${esc(u.email)}</small></td><td>${esc(u.organization_name||'PulseFlow')}</td><td>${u.role==='super_admin'?'ADM global':u.role==='owner'?'Proprietário':'Usuário'}</td><td>${dateTime(u.last_login_at)}</td><td>${u.role==='super_admin'?'<span class="pill purple">Protegido</span>':`<button class="text-button" data-user-status="${esc(u.id)}" data-status="${u.status==='active'?'suspended':'active'}">${u.status==='active'?'Suspender':'Reativar'}</button>`}</td></tr>`).join('')}</tbody></table></div></section><section class="panel spaced"><h2>Últimas ações de suporte</h2>${a.audits?.length?`<div class="audit-list">${a.audits.map(log=>`<div><span>${icon('shield')}</span><p><b>${esc(log.organization_name||'Plataforma')}</b><small>${esc(log.action)} · ${esc(log.actor_name)} · ${dateTime(log.created_at)}</small></p></div>`).join('')}</div>`:'<p>Nenhum acesso de suporte registrado.</p>'}</section>`}
async function refreshAIStatus(){if(!S.user||!S.account||!permission('workspace_read'))return;const org=S.account.id,token=S.loadToken;try{const value=await ai('status&organization_id='+encodeURIComponent(org));if(S.loadToken!==token||S.account?.id!==org)return;S.aiStatus=value;if(S.page==='conversations'&&!$('#modal'))render()}catch(error){if(S.loadToken===token&&S.account?.id===org)S.aiStatus={configured:false,error:error.message}}}
function aiInsight(l){const local='<p class="fine-print">As três dicas acima continuam disponíveis sem custo de IA.</p>',analysis=S.aiAnalysis?.leadId===l.id?S.aiAnalysis.analysis:null;if(!S.workspace.ai?.enabled)return `<section class="ai-insight"><span class="ai-badge">IA REAL · PAUSADA</span><h3>Ative o agente desta empresa</h3><p>Defina objetivo, tom e regras antes da primeira análise.</p><button type="button" class="btn secondary wide" data-page="automations">Configurar agente</button>${local}</section>`;if(!S.aiStatus?.configured)return `<section class="ai-insight"><span class="ai-badge">IA REAL · AGUARDANDO</span><h3>Integração protegida no servidor</h3><p>${esc(S.aiStatus?.error||'O administrador ainda precisa ativar o provedor de IA.')}</p>${local}</section>`;if(!analysis)return `<section class="ai-insight"><span class="ai-badge online">IA REAL · ATIVA</span><h3>Analisar esta conversa</h3><p>A IA usa mensagens, notas, ligações e memórias desta empresa. Ela apenas sugere; você decide.</p><button type="button" class="btn primary wide" data-ai-action="analyze" ${S.aiLoading||!permission('workspace_write')?'disabled':''}>${S.aiLoading?'Analisando…':icon('spark')+' Analisar com IA'}</button><small>${S.aiStatus.remaining_today} de ${S.aiStatus.daily_limit} análises disponíveis hoje.</small>${local}</section>`;const labels={call:'Ligar',message:'Preparar mensagem',meeting:'Propor reunião',wait:'Aguardar',none:'Somente observar'};return `<section class="ai-insight has-result"><span class="ai-badge online">ANÁLISE DA IA · REVISÃO OBRIGATÓRIA</span><h3>${esc(labels[analysis.recommended_next_action]||'Próximo passo')}</h3><p>${esc(analysis.summary)}</p><dl><dt>Intenção</dt><dd>${esc(analysis.intent||'Não identificada')}</dd><dt>Consciência</dt><dd>${esc(analysis.awareness||'Não identificada')}</dd><dt>Por quê</dt><dd>${esc(analysis.follow_up_reason||'Revise o contexto antes de agir.')}</dd></dl>${analysis.signals?.length?`<div class="ai-signals">${analysis.signals.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}${analysis.suggested_message?`<blockquote>${esc(analysis.suggested_message)}</blockquote><button type="button" class="btn primary wide" data-ai-action="use">Usar sugestão na conversa</button>`:''}<button type="button" class="btn text wide" data-ai-action="analyze">Analisar novamente</button><small>Confiança ${Math.round(Number(analysis.confidence||0)*100)}% · nada foi enviado automaticamente.</small></section>`}
function enhanceConversationAI(){if(S.page!=='conversations'||S.chatTab!=='tips')return;const target=$('.chat-context>.fine-print');const l=currentLead();if(target&&l)target.outerHTML=aiInsight(l)}
async function analyzeLead(){const l=currentLead();if(!l||S.aiLoading)return;S.aiLoading=true;render();try{await flush();const data=await ai('analyze',{organization_id:S.account.id,lead_id:l.id});S.aiAnalysis={leadId:l.id,analysisId:data.analysis_id,analysis:data.analysis};S.aiStatus={...S.aiStatus,used_today:data.used_today,daily_limit:data.daily_limit,remaining_today:Math.max(0,data.daily_limit-data.used_today)};if(S.workspace.ai.learningEnabled){S.workspace.ai.memories.push({id:data.analysis_id,leadId:l.id,leadName:l.name,summary:data.analysis.summary,signals:data.analysis.signals,at:new Date().toISOString(),source:'openai'});S.workspace.ai.memories=S.workspace.ai.memories.slice(-500)}if(data.analysis.suggested_message&&!S.workspace.manualApprovals.some(a=>a.id===data.analysis_id)){S.workspace.manualApprovals.unshift({id:data.analysis_id,leadId:l.id,leadName:l.name,status:'pending',createdAt:new Date().toISOString(),title:'Sugestão da IA',summary:data.analysis.follow_up_reason,text:data.analysis.suggested_message})}changed();await flush();toast('Análise concluída. Revise a sugestão antes de agir.')}catch(error){toast(error.message,true)}finally{S.aiLoading=false;render()}}
function render(){if(!S.user)return login();app.innerHTML=shell(({home,leads,conversations,agenda,automations,settings,cadence,admin}[S.page]||home)());saveStatus();renderAlerts();enhanceConversationAI();if(S.page==='conversations')$('#messages')?.scrollTo(0,999999);if(S.page==='settings')updateNicheField()}
function dialog(title,body,size=''){closeDialog();focusBeforeDialog=document.activeElement;const d=document.createElement('dialog');d.id='modal';d.className='modal '+size;d.innerHTML=`<header class="modal-header"><div><span class="eyebrow">PULSEFLOW · SEU ESPAÇO</span><h2>${title}</h2></div><button class="icon-button" data-action="close" aria-label="Fechar janela">${icon('close')}</button></header>${body}`;document.body.append(d);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});d.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});d.showModal();d.querySelector('input,select,textarea,button')?.focus()}
function closeDialog(){const d=$('#modal');if(d){d.close();d.remove();focusBeforeDialog?.focus?.()}}
const formEnd=(text='Salvar')=>`<p class="form-error" role="alert"></p><footer class="modal-actions">${button('Cancelar','close','secondary','type="button"')}<button class="btn primary" type="submit">${text}</button></footer>`;
function onboarding(){const w=S.workspace;dialog('Seu negócio, seu jeito.',`<p class="modal-description">Duas informações para deixar tudo com a sua cara.</p><form id="business-form">${field('Nome da empresa','businessName',w.whatsapp.businessName||S.account.name,'required maxlength="120"')}${field('Seu WhatsApp com DDD','number',w.whatsapp.number,'type="tel" placeholder="(11) 99999-9999"')}${select('Nicho','niche',[...NICHES,'Outro'],w.businessProfile.customNiche?'Outro':w.businessProfile.niche||'Serviços')}${field('Qual é o seu nicho?','customNiche',w.businessProfile.customNiche,'maxlength="100"')}<div class="notice subtle">No modo manual, você abre o WhatsApp e envia a mensagem por lá.</div>${formEnd('Salvar e começar')}</form>`);updateNicheField()}
function updateNicheField(){const root=$('#modal')||document,sel=root.querySelector('[name="niche"]'),custom=root.querySelector('[name="customNiche"]');if(sel&&custom){custom.closest('.field').hidden=sel.value!=='Outro';custom.required=sel.value==='Outro'}}
function leadForm(item){const l=item||{board:S.board,interest:'Média',phone:'',notes:''};dialog(item?'Contexto de '+esc(item.name):'Um novo contato.',`<form id="lead-form" data-id="${l.id||''}"><div class="form-grid">${field('Nome','name',l.name,'required maxlength="120"')}${field('WhatsApp com DDD','phone',l.phone,'required type="tel"')}${field('Origem','origin',l.origin,'placeholder="Instagram, anúncio, indicação…" maxlength="100"')}${select('Interesse','interest',['Alta','Média','Baixa'],l.interest)}</div>${check('Este contato autorizou o atendimento pelo WhatsApp','consentConfirmed',l.consentConfirmed)}<details class="advanced" ${item?'open':''}><summary>Notas, contrato e próximos passos</summary>${textarea('Necessidade do cliente','needs',l.needs,'maxlength="1000"')}${textarea('Notas e contexto','notes',l.notes,'rows="4" maxlength="10000"')}<div class="form-grid">${field('Produto / serviço','product',l.product,'maxlength="120"')}${field('Valor do contrato (R$)','contractValue',l.contractValue||'','type="number" min="0" step="0.01"')}${field('Nicho do cliente','niche',l.niche,'maxlength="100"')}${field('Faturamento informado','revenue',l.revenue,'maxlength="100"')}${select('Pipeline','board',BOARDS,l.board)}${select('Etapa','stage',(l.board==='Pós-venda'?S.workspace.postSaleColumns:S.workspace.columns).map(c=>[c.id,c.name]),l.stage||'new')}${select('Próxima ação','nextAction',['Ligação','Mensagem','Reunião'],l.nextAction||'Ligação')}${field('Data e hora','nextDate',l.nextDate||'','type="datetime-local"')}</div><details class="advanced"><summary>Recuperação e preferência de contato</summary>${field('Motivo do descarte','discardReason',l.discardReason,'placeholder="Ex.: orçamento indisponível neste mês" maxlength="500"')}${field('Revisar recuperação em','recoveryAt',l.recoveryAt?localDateTime(l.recoveryAt):'','type="datetime-local"')}${check('Não contatar — respeitar pedido do cliente','optOut',l.optOut)}<p class="fine-print">Contatos em Abandonados precisam de motivo e data. Um pedido para não receber mensagens impede reativação.</p></details></details>${formEnd(item?'Salvar alterações':'Criar contato')}</form>`,'wide-modal')}
function columnForm(column){const c=column||{limit:24,name:'',aiObserver:{},aiOperator:{},automations:{}};dialog(column?'Configurar etapa':'Nova etapa',`<form id="column-form" data-id="${c.id||''}">${field('Nome da etapa','name',c.name,'required maxlength="80"')}${field('Tempo limite na etapa (horas)','limit',c.limit,'type="number" min="0" max="17520" required')}<p class="fine-print">O prazo destaca contatos pendentes. Não dispara mensagens.</p><details class="advanced"><summary>Cadência e instruções dos agentes</summary>${check('Preparar acompanhamento ao entrar nesta etapa','followUp',c.automations?.followUp)}${field('Primeiro lembrete após (horas)','delay',c.delay??24,'type="number" min="0" max="17520"')}${textarea('Contexto para a observadora','observerInstructions',c.aiObserver?.instructions||'')}${S.board!=='Pós-venda'?textarea('Objetivo da operadora','operatorInstructions',c.aiOperator?.instructions||''):''}<span class="pill neutral">IA não conectada · instruções salvas</span><p class="fine-print">Cada envio precisa de aprovação. No pós-venda apenas observação é permitida.</p></details>${formEnd('Salvar etapa')}</form>`)}
function automationRuleForm(rule){const r=rule||{enabled:true,trigger:'stage_timeout',board:'Principal',delay:24,action:'prepare_followup',instructions:''};dialog(rule?'Editar automação':'Nova automação',`<form id="automation-form" data-id="${r.id||''}">${check('Regra ativa','enabled',r.enabled)}${field('Nome da automação','name',r.name,'required maxlength="120"')}${select('Quando acontece','trigger',[['stage_timeout','Prazo da etapa vencido'],['reply_received','Cliente respondeu'],['inactive_lead','Contato ficou inativo'],['post_sale_signal','Sinal no pós-venda']],r.trigger)}${select('Pipeline','board',['Todos',...BOARDS],r.board||'Todos')}${field('Esperar (horas)','delay',r.delay||0,'type="number" min="0" max="17520" required')}${select('Ação do agente','action',[['prepare_followup','Preparar follow-up para aprovação'],['notify_seller','Avisar o vendedor'],['observe_only','Somente observar e registrar']],r.action)}${textarea('Instrução para o agente','instructions',r.instructions,'maxlength="2000" placeholder="Explique o que deve ser observado ou preparado."')}<div class="notice subtle">A regra nunca envia mensagem sozinha. No pós-venda, use somente observação.</div>${formEnd('Salvar automação')}</form>`)}
function callForm(){const l=currentLead();if(!l)return toast('Adicione um contato primeiro.');if(!canContact(l))return toast('Contato fechado, em pós-venda ou com bloqueio de contato.',true);dialog('Registrar ligação',`<p class="modal-description">${esc(l.name)} · ${esc(l.phone)}</p><form id="call-form">${select('Resultado','outcome',['Não atendeu','Conversa realizada','Reunião combinada'],'Não atendeu')}${textarea('O que você aprendeu ou combinou?','note','','maxlength="5000"')}<a class="btn secondary" href="tel:+${phoneNumber(l.phone)}">${icon('phone')} Abrir discador</a>${formEnd('Registrar tentativa')}</form>`)}
function scheduleForm(){const l=currentLead();if(!l)return toast('Adicione um contato antes de agendar.');dialog('Combine o próximo passo.',`<form id="schedule-form">${select('Contato','leadId',S.workspace.leads.map(x=>[x.id,x.name]),l.id)}${select('Tipo de contato','nextAction',['Ligação','Mensagem','Reunião'],l.nextAction||'Ligação')}${field('Quando','nextDate',l.nextDate||localDateTime(),'type="datetime-local" required')}${textarea('Objetivo deste contato','note','','placeholder="O que vale retomar nesta conversa?" maxlength="2000"')}<p class="fine-print">O agendamento aparece na agenda do PulseFlow. Não envia mensagens ou convites por conta própria.</p>${formEnd('Agendar contato')}</form>`)}
function leadCadence(){const l=currentLead();dialog('Acompanhamento de '+esc(l.name),`<p class="modal-description">Mensagens diferentes, no seu ritmo. Os intervalos começam na ativação da sequência.</p><div class="cadence-picker">${S.workspace.cadence.map((step,i)=>`<button ${step.action==='Ligar'?'data-action="call"':`data-cadence-text="${i}"`}><span>${i+1}</span><div><b>Após ${step.delay} ${esc(step.unit)}</b><p>${esc(step.text)}</p></div>${icon('arrow')}</button>`).join('')}</div><footer class="modal-actions">${button(l.cadenceEnabled&&!l.automationPaused?'Pausar sequência':'Ativar sequência','toggle-cadence','primary')}${button('Fechar','close','secondary')}</footer>`)}
function manageAccount(org){const o=S.admin.accounts.find(a=>a.id===org);dialog('Gerenciar '+esc(o.name),`<form id="account-form" data-org="${esc(o.id)}">${select('Plano','plan',['Base','Equipe'],o.plan)}${select('Status da empresa','status',[['active','Ativa'],['suspended','Suspensa']],o.status)}<h3>Permissões desta conta</h3>${[['workspace_read','Acessar o espaço'],['workspace_write','Editar contatos e agenda'],['manage_settings','Configurar regras e negócio'],['whatsapp_read','Ler mensagens oficiais'],['whatsapp_send','Enviar mensagens oficiais'],['whatsapp_manage','Gerenciar credenciais']].map(([k,label])=>check(label,k,o.permissions?.[k]!==false)).join('')}<p class="fine-print">A suspensão encerra o acesso dos usuários da empresa. O administrador mantém acesso de suporte.</p>${formEnd('Salvar acesso')}</form>`)}
function memberForm(){dialog('Adicionar vendedor',`<p class="modal-description">A pessoa entrará no mesmo espaço da empresa. Compartilhe a senha inicial por um canal seguro.</p><form id="member-form">${field('Nome','name','','required maxlength="160" autocomplete="name"')}${field('E-mail','email','','type="email" required maxlength="254" autocomplete="username"')}${field('Senha inicial','password','','type="password" required minlength="10" maxlength="128" autocomplete="new-password"')}<div class="notice subtle">O vendedor acessa contatos, agenda e conversas da empresa. Somente o proprietário administra a equipe.</div>${formEnd('Criar acesso')}</form>`)}
function passwordForm(){dialog('Alterar minha senha',`<form id="password-form">${field('Senha atual','current_password','','type="password" required maxlength="128" autocomplete="current-password"')}${field('Nova senha','new_password','','type="password" required minlength="10" maxlength="128" autocomplete="new-password"')}<p class="fine-print">As outras sessões da sua conta serão encerradas.</p>${formEnd('Alterar senha')}</form>`)}
async function refreshChannel(){if(polling||!S.user||!S.account||!permission('whatsapp_read'))return;polling=true;const org=S.account.id,token=S.loadToken;try{const c=await wa('connection&organization_id='+encodeURIComponent(org));if(S.loadToken!==token||S.account?.id!==org)return;S.connection=c;if(c.ready){const data=await wa('messages&organization_id='+encodeURIComponent(org)+'&limit=100&cursor='+encodeURIComponent(S.cursor||'0'));if(S.loadToken!==token||S.account?.id!==org)return;for(const m of data.messages){const idx=S.remote.findIndex(x=>x.wa_message_id===m.wa_message_id);if(idx>=0)S.remote[idx]=m;else S.remote.push(m);if(m.direction==='in'&&permission('workspace_write')){const phone=phoneNumber(m.contact_phone);if(!phone)continue;let l=S.workspace.leads.find(x=>phoneNumber(x.phone)===phone);if(!l){l={id:id(),name:m.contact_name||phone,phone,origin:'WhatsApp',interest:'Média',board:'Principal',stage:'new',entered:Date.now(),messages:[],calls:[],notes:'',consentConfirmed:false};S.workspace.leads.push(l)}if(l.lastReplyId!==m.wa_message_id&&new Date(m.occurred_at).getTime()>=new Date(l.lastReplyAt||0).getTime()){l.automationPaused=true;l.lastReplyId=m.wa_message_id;l.lastReplyAt=m.occurred_at;l.last=m.body||'Nova mensagem';learnFromConversation(l,m.body,'in');processAutomations('reply_received',l);if(l.board==='Pós-venda')processAutomations('post_sale_signal',l);toast('Resposta recebida de '+l.name+'. A cadência foi pausada.');S.workspace.notifications.unshift({id:m.wa_message_id,leadId:l.id,text:'Resposta recebida de '+l.name,at:m.occurred_at});if(permission('workspace_write'))changed()}}}S.cursor=data.next_cursor||S.cursor}if(['home','conversations','automations'].includes(S.page)&&!$('#message-input')?.value&&!$('#modal'))render()}catch(e){S.connection={...S.connection,error:e.message}}finally{polling=false}}
async function sendMessage(form){const l=currentLead(),text=String(new FormData(form).get('text')||'').trim();if(!l||!text)return;if(l.pendingManual)throw new Error('Confirme ou descarte a mensagem anterior antes de preparar outra.');if(!permission('workspace_write'))throw new Error('Sua conta não permite editar contatos.');if(!canContact(l)||!callRecorded(l))throw new Error('Confira a ligação inicial e a preferência de contato.');if(!l.consentConfirmed)throw new Error('Confirme nas notas que o contato autorizou o atendimento.');const phone=phoneNumber(l.phone);if(!phone)throw new Error('Informe um WhatsApp válido com DDD.');if(S.connection?.ready){if(!permission('whatsapp_send'))throw new Error('Envio oficial desativado nesta conta.');await flush();const requestId=l.pendingRequest?.text===text?l.pendingRequest.id:id();l.pendingRequest={id:requestId,text};changed();await flush();const result=await wa('send',{organization_id:S.account.id,lead_id:l.id,approval:true,request_id:requestId,text});delete l.pendingRequest;l.last=text;l.lastContactAt=new Date().toISOString();recordTask(l,'Mensagem aceita pela Meta',true);changed();toast('Mensagem aceita pela Meta. A entrega será atualizada na conversa.');await refreshChannel()}else{window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');l.pendingManual={text,preparedAt:new Date().toISOString()};toast('Confira o WhatsApp. Confirme aqui somente depois de enviar.')}S.draft='';changed();render()}

document.addEventListener('submit',async e=>{const form=e.target;if(!['member-form','password-form'].includes(form.id))return;e.preventDefault();e.stopImmediatePropagation();const submit=form.querySelector('button[type="submit"]'),v=Object.fromEntries(new FormData(form));if(submit)submit.disabled=true;try{if(form.id==='member-form'){await auth('team-user',{organization_id:S.account.id,operation:'create',...v});closeDialog();await loadTeam();toast('Acesso do vendedor criado.')}else{await auth('change-password',v);closeDialog();toast('Senha alterada. As outras sessões foram encerradas.')}}catch(error){const el=form.querySelector('.form-error');if(el)el.textContent=error.message;else toast(error.message,true)}finally{if(submit)submit.disabled=false}},true);
document.addEventListener('click',async e=>{const settings=e.target.closest('[data-settings="security"]'),teamButton=e.target.closest('[data-team-status]');if(!settings&&!teamButton)return;e.stopImmediatePropagation();try{if(settings){S.settingsTab='security';S.team=null;render();await loadTeam();return}if(!confirm(`Confirmar que deseja ${teamButton.dataset.teamStatus==='active'?'reativar':'suspender'} este usuário?`))return;await auth('team-user',{organization_id:S.account.id,operation:'status',user_id:teamButton.dataset.teamUser,status:teamButton.dataset.teamStatus});await loadTeam();toast('Acesso da equipe atualizado.')}catch(error){toast(error.message,true)}},true);

document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('form'))return;e.preventDefault();const submit=form.querySelector('button[type="submit"],button:not([type])'),v=Object.fromEntries(new FormData(form));if(submit)submit.disabled=true;try{if(form.id==='auth-form'){const data=await auth(form.dataset.register==='true'?'register':'login',v);S.user=data.user;S.dirty=false;S.conflict=false;if(isAdmin()){S.page='admin';await loadAdmin()}else await openWorkspace(data.user.organization_id);return}if(form.id==='composer'){await sendMessage(form);return}if(!permission('workspace_write')&&!['account-form'].includes(form.id))throw new Error('Sua conta está com edição desativada.');if(['business-form','rules-form','ai-form','agent-form','automation-form','column-form','cadence-form','whatsapp-form','webhook-form'].includes(form.id)&&!permission('manage_settings'))throw new Error('Configurações restritas nesta conta.');switch(form.id){case 'business-form':{const n=phoneNumber(v.number);if(v.number&&!n)throw new Error('Informe o número com DDD.');S.workspace.whatsapp={number:n,businessName:v.businessName.trim()};S.workspace.businessProfile={niche:v.niche==='Outro'?'Serviços':v.niche,customNiche:v.niche==='Outro'?v.customNiche.trim():'',onboarded:true};break}case 'lead-form':{const phone=phoneNumber(v.phone);if(!phone)throw new Error('Confira o número com DDD.');if(v.board==='Abandonados'&&(!v.discardReason?.trim()||!v.recoveryAt))throw new Error('Informe o motivo do descarte e a data de recuperação.');let l=S.workspace.leads.find(x=>x.id===form.dataset.id);if(!l){l={id:id(),entered:Date.now(),messages:[],calls:[],notes:''};S.workspace.leads.push(l)}const columns=v.board==='Pós-venda'?S.workspace.postSaleColumns:S.workspace.columns;if(l.stage!==v.stage||l.board!==v.board)l.entered=Date.now();Object.assign(l,v,{phone,consentConfirmed:!!v.consentConfirmed,optOut:!!v.optOut,contractValue:Number(v.contractValue)||0,stage:columns.some(c=>c.id===v.stage)?v.stage:columns[0].id});if(l.optOut)l.automationPaused=true;S.selected=l.id;break}case 'column-form':{const columns=S.board==='Pós-venda'?S.workspace.postSaleColumns:S.workspace.columns;let c=columns.find(x=>x.id===form.dataset.id);if(!c){c={id:id()};columns.push(c)}Object.assign(c,{name:v.name.trim(),limit:Number(v.limit),delay:Number(v.delay),aiObserver:{enabled:false,instructions:v.observerInstructions||''},aiOperator:{enabled:false,instructions:S.board==='Pós-venda'?'':v.operatorInstructions||'',mode:'Somente sugerir'},automations:{followUp:!!v.followUp,callFirst:true,pauseOnReply:true}});break}case 'call-form':{const l=currentLead();l.calls.push({id:id(),at:new Date().toISOString(),outcome:v.outcome,note:v.note});l.callDone=true;l.lastContactAt=new Date().toISOString();if(v.note){l.notes+=(l.notes?'\n\n':'')+'Ligação: '+v.note;learnFromConversation(l,v.note,'call')}recordTask(l,'Ligação · '+v.outcome);break}case 'schedule-form':{const l=S.workspace.leads.find(x=>x.id===v.leadId);l.nextAction=v.nextAction;l.nextDate=v.nextDate;if(v.note)l.notes+=(l.notes?'\n\n':'')+'Próximo contato: '+v.note;break}case 'rules-form':Object.assign(S.workspace.settings,{inactiveDays:Number(v.inactiveDays),recoveryDays:Number(v.recoveryDays)});break;case 'ai-form':S.workspace.ai={...S.workspace.ai,...v};break;case 'agent-form':S.workspace.ai={...S.workspace.ai,name:v.name.trim(),goal:v.goal.trim(),tone:v.tone,observerInstructions:v.observerInstructions||'',operatorInstructions:v.operatorInstructions||'',enabled:!!v.enabled,learningEnabled:!!v.learningEnabled,memoryRetentionDays:Number(v.memoryRetentionDays)||180,autonomy:'suggest_only'};processAutomations();break;case 'automation-form':{if(v.board==='Pós-venda'&&v.action!=='observe_only')throw new Error('No pós-venda, o agente pode somente observar e registrar.');let r=S.workspace.automations.find(x=>x.id===form.dataset.id);if(!r){r={id:id()};S.workspace.automations.push(r)}Object.assign(r,{name:v.name.trim(),enabled:!!v.enabled,trigger:v.trigger,board:v.board,delay:Number(v.delay)||0,action:v.action,instructions:v.instructions||''});break}case 'cadence-form':S.workspace.cadence=S.workspace.cadence.map((s,i)=>({...s,delay:Number(v['delay-'+i]),unit:v['unit-'+i],text:v['text-'+i]}));break;case 'account-form':{const permissions=Object.fromEntries(['workspace_read','workspace_write','manage_settings','whatsapp_read','whatsapp_send','whatsapp_manage'].map(k=>[k,!!v[k]]));await auth('admin-account',{organization_id:form.dataset.org,plan:v.plan,status:v.status,permissions});closeDialog();await loadAdmin();toast('Acesso da conta atualizado.');return}case 'webhook-form':{await wa('prepare-webhook',{organization_id:S.account.id,...v});form.reset();await refreshChannel();render();toast('Webhook preparado. Use a URL e o mesmo token na Meta.');return}case 'whatsapp-form':{await flush();await wa('connect',{organization_id:S.account.id,business_number:S.workspace.whatsapp.number,...v});form.reset();await refreshChannel();render();toast('Credenciais configuradas. Confira a validação e o webhook.');return}default:return}processDueReviews();changed();await flush();closeDialog();render();toast('Salvo. Seu próximo passo está organizado.')}catch(error){const el=form.querySelector('.form-error');if(el)el.textContent=error.message;else toast(error.message,true)}finally{if(submit)submit.disabled=false}});
function recordTask(l,title,advance=false){S.workspace.reminders.unshift({id:id(),leadId:l.id,title:l.name+' · '+title,done:true,completedAt:new Date().toISOString()});for(const approval of S.workspace.manualApprovals||[])if(approval.leadId===l.id&&['pending','reviewing'].includes(approval.status))approval.status='completed';l.nextDate='';l.lastTaskCompletedAt=Date.now();if(l.board==='Abandonados'){l.recoveryAt='';l.automationPaused=true}if(l.cadenceEnabled&&(advance||(title.startsWith('Ligação')&&S.workspace.cadence[l.cadenceIndex||0]?.action==='Ligar')))l.cadenceIndex=(l.cadenceIndex||0)+1}
async function action(name){if(['toggle-cadence','confirm-manual','cancel-manual','add-step'].includes(name)&&!permission('workspace_write'))throw new Error('Edição desativada nesta conta.');if(['add-step','automation-rule'].includes(name)&&!permission('manage_settings'))throw new Error('Configurações restritas nesta conta.');switch(name){case 'close':return closeDialog();case 'lead':return leadForm();case 'onboarding':case 'number':return onboarding();case 'notes':return leadForm(currentLead());case 'column':return columnForm();case 'automation-rule':return automationRuleForm();case 'member':return memberForm();case 'password':return passwordForm();case 'call':return callForm();case 'schedule':case 'schedule-select':return scheduleForm();case 'menu':S.menu=!S.menu;return render();case 'logout':await flush();await auth('logout',{});S.loadToken++;S.cursor='0';S.team=null;S.workspace=freshWorkspace();S.dirty=false;S.remote=[];return login();case 'retry':return flush();case 'export':return exportWorkspace();case 'export-leads':return exportLeadsCsv();case 'reload-workspace':if(confirm('Recarregar os dados salvos no servidor? Baixe uma cópia para preservar alterações locais.')){S.dirty=false;S.conflict=false;return openWorkspace(S.account.id,S.support)}return;case 'exit-support':await flush();S.account=null;S.team=null;S.workspace=freshWorkspace();S.connection=null;S.remote=[];S.support=false;S.cursor='0';return loadAdmin();case 'refresh-admin':return loadAdmin();case 'cadence':S.page='cadence';break;case 'pipeline-settings':S.page='leads';break;case 'back-settings':S.page='settings';S.settingsTab='operation';break;case 'suggest-first':{const l=currentLead();if(!l)return leadForm();S.selected=l.id;S.page='conversations';S.draft=suggestions(S.workspace.businessProfile.niche,l)[0];break}case 'lead-cadence':return leadCadence();case 'toggle-cadence':{const l=currentLead();if(!canContact(l))throw new Error('Este contato não permite acompanhamento ativo.');l.cadenceEnabled=true;l.automationPaused=l.cadenceStarted?!l.automationPaused:false;if(!l.cadenceStarted){l.cadenceStarted=Date.now();l.cadenceIndex=S.workspace.cadence[0]?.action==='Ligar'&&callRecorded(l)?1:0}changed();closeDialog();break}case 'confirm-manual':{const l=currentLead();if(!l.pendingManual)return;const text=l.pendingManual.text;l.messages.push({id:id(),direction:'out',body:text,at:new Date().toISOString(),status:'confirmed_manual'});l.last=text;l.lastContactAt=new Date().toISOString();delete l.pendingManual;learnFromConversation(l,text,'out');recordTask(l,'Mensagem enviada · confirmação manual',true);changed();break}case 'cancel-manual':delete currentLead().pendingManual;changed();break;case 'validate-wa':{S.connection=await wa('validate',{organization_id:S.account.id});toast(S.connection.ready?'WhatsApp oficial conectado.':'Credenciais válidas. Agora conclua o webhook na Meta.');break}case 'add-step':syncCadenceDraft();S.workspace.cadence.push({id:id(),delay:1,unit:'dias',text:'Oi, {nome}! Faz sentido retomar nossa conversa?'});changed();break;default:return}render()}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-open]');if(!b)return;try{if(b.dataset.authSwitch!==undefined)return login('',b.dataset.authSwitch==='true');if(b.dataset.action){if(b.type==='submit'&&b.closest('form'))return;await action(b.dataset.action);return}if(b.dataset.page){S.page=b.dataset.page;S.menu=false;S.search='';render()}if(b.dataset.board){S.board=b.dataset.board;S.search='';render()}if(b.dataset.open)leadAction(S.workspace.leads.find(l=>l.id===b.dataset.open));if(b.dataset.notes){S.selected=b.dataset.notes;leadForm(currentLead())}if(b.dataset.configColumn)columnForm((S.board==='Pós-venda'?S.workspace.postSaleColumns:S.workspace.columns).find(c=>c.id===b.dataset.configColumn));if(b.dataset.agenda){S.agenda=b.dataset.agenda;render()}if(b.dataset.settings){S.settingsTab=b.dataset.settings;render()}if(b.dataset.chatTab){S.draft=$('#message-input')?.value||S.draft;S.chatTab=b.dataset.chatTab;render()}if(b.dataset.template){S.draft=suggestions(S.workspace.businessProfile.niche,currentLead())[Number(b.dataset.template)];$('#message-input').value=S.draft}if(b.dataset.calendar)downloadCalendar(b.dataset.calendar);if(b.dataset.schedule){S.selected=b.dataset.schedule;scheduleForm()}if(b.dataset.complete){if(!permission('workspace_write'))throw new Error('Edição desativada nesta conta.');const l=S.workspace.leads.find(x=>x.id===b.dataset.complete);if(!callRecorded(l)){S.selected=l.id;callForm();return}recordTask(l,l.nextAction||'Acompanhamento concluído');changed();render()}if(b.dataset.cadenceText){S.draft=S.workspace.cadence[Number(b.dataset.cadenceText)].text.replaceAll('{nome}',currentLead().name.split(' ')[0]);closeDialog();render()}if(b.dataset.removeStep){if(!permission('manage_settings'))throw new Error('Configurações restritas nesta conta.');syncCadenceDraft();S.workspace.cadence.splice(Number(b.dataset.removeStep),1);changed();render()}if(b.dataset.editAutomation){if(!permission('manage_settings'))throw new Error('Configurações restritas nesta conta.');automationRuleForm(S.workspace.automations.find(r=>r.id===b.dataset.editAutomation))}if(b.dataset.toggleAutomation){if(!permission('manage_settings'))throw new Error('Configurações restritas nesta conta.');const r=S.workspace.automations.find(x=>x.id===b.dataset.toggleAutomation);if(r){r.enabled=!r.enabled;changed();render()}}if(b.dataset.reviewAutomation){const a=S.workspace.manualApprovals.find(x=>x.id===b.dataset.reviewAutomation),l=S.workspace.leads.find(x=>x.id===a?.leadId);if(l){a.status='reviewing';S.selected=l.id;S.draft=a.text||'';S.page='conversations';changed();render()}}if(b.dataset.dismissAutomation){const a=S.workspace.manualApprovals.find(x=>x.id===b.dataset.dismissAutomation);if(a){a.status='dismissed';changed();render()}}if(b.dataset.support)await openWorkspace(b.dataset.support,true);if(b.dataset.manageAccount)manageAccount(b.dataset.manageAccount);if(b.dataset.userStatus&&confirm('Confirmar a alteração de acesso deste usuário?')){await auth('admin-user',{user_id:b.dataset.userStatus,status:b.dataset.status});await loadAdmin()}}catch(error){toast(error.message,true)}});
document.addEventListener('input',e=>{if(e.target.id==='lead-search'){S.search=e.target.value;const start=e.target.selectionStart;const value=S.search;render();$('#lead-search')?.focus();$('#lead-search')?.setSelectionRange(start,start)}if(e.target.id==='chat-search'){const term=e.target.value.toLowerCase();$$('.conversation-item').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(term))}if(e.target.id==='message-input')S.draft=e.target.value});
document.addEventListener('change',e=>{if(e.target.name==='niche')updateNicheField();if(e.target.name==='board'){if(e.target.value==='Abandonados'){const recovery=$('#lead-form [name="recoveryAt"]');if(recovery&&!recovery.value)recovery.value=localDateTime(Date.now()+Number(S.workspace.settings.recoveryDays||30)*86400000)}const columns=e.target.value==='Pós-venda'?S.workspace.postSaleColumns:S.workspace.columns;const s=$('#lead-form [name="stage"]');if(s)s.innerHTML=columns.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}});
document.addEventListener('change',async e=>{if(e.target.id!=='crm-import')return;const file=e.target.files?.[0];e.target.value='';try{await importLeadsCsv(file)}catch(error){toast(error.message,true)}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag]');if(card)e.dataTransfer.setData('text/plain',card.dataset.drag)});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-column]'))e.preventDefault()});
document.addEventListener('drop',e=>{const col=e.target.closest('[data-column]');if(!col)return;e.preventDefault();if(!permission('workspace_write'))return toast('Edição desativada nesta conta.',true);const l=S.workspace.leads.find(x=>x.id===e.dataTransfer.getData('text/plain'));if(!l||l.stage===col.dataset.column)return;l.stage=col.dataset.column;l.entered=Date.now();const c=(S.board==='Pós-venda'?S.workspace.postSaleColumns:S.workspace.columns).find(x=>x.id===l.stage);if(c?.automations?.followUp&&canContact(l)){l.nextAction=callRecorded(l)?'Mensagem':'Ligação';l.nextDate=localDateTime(Date.now()+Number(c.delay??24)*3600000)}changed();render()});
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue=''}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ai-action]');if(!b)return;try{if(b.dataset.aiAction==='analyze')await analyzeLead();if(b.dataset.aiAction==='use'&&S.aiAnalysis?.analysis?.suggested_message){S.draft=S.aiAnalysis.analysis.suggested_message;render();$('#message-input')?.focus()}}catch(error){toast(error.message,true)}});
document.addEventListener('click',e=>{const alerts=e.target.closest('[data-alerts]'),lead=e.target.closest('[data-alert-lead]');if(alerts)return alertCenter();if(lead){const item=S.workspace.leads.find(x=>x.id===lead.dataset.alertLead);if(item){closeDialog();leadAction(item)}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(!b)return;const input=document.getElementById(b.dataset.copy);if(!input)return;try{await navigator.clipboard.writeText(input.value);toast('Copiado com segurança.')}catch(error){input.focus();input.select();toast('Selecione e copie o texto destacado.')}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshChannel();if(processDueReviews()+processAutomations()){changed();render()}}});
setInterval(()=>{if(!document.hidden)refreshChannel()},30000);
setInterval(()=>{if(!document.hidden&&S.account&&processDueReviews()){changed();if(['home','agenda','automations'].includes(S.page)&&!$('#modal'))render()}},60000);
function syncCadenceDraft(){const f=$('#cadence-form');if(!f)return;const v=Object.fromEntries(new FormData(f));S.workspace.cadence=S.workspace.cadence.map((s,i)=>({...s,delay:Number(v['delay-'+i])||0,unit:v['unit-'+i]||s.unit,text:v['text-'+i]??s.text}))}
boot();
